import json, os, csv, glob
man = json.load(open('inputs/manifest.json'))
print('manifest keys:', list(man.keys())[:10])
files = man.get('files') or man.get('inputs') or []
print('files:', json.dumps(files)[:800])
paths = []
def walk(o):
    if isinstance(o, dict):
        for k,v in o.items():
            if isinstance(v,str) and v.lower().endswith(('.csv','.xlsx','.xls')):
                paths.append(v)
            else:
                walk(v)
    elif isinstance(o, list):
        for v in o: walk(v)
walk(man)
print('candidate paths:', paths[:5])
for p in paths[:3]:
    if os.path.exists(p):
        with open(p, newline='', encoding='utf-8-sig') as f:
            rows = list(csv.reader(f))
        print('PATH', p, 'nrows', len(rows), 'header', rows[0])
        for i,r in enumerate(rows[1:], start=2):
            print(i, r)
        break

